test_optional_shell_guard_accepts_undef_.code:
define example::guard (String $argument, Boolean $enabled = true) {
  if $enabled {
    $argument_shell = stdlib::shell_escape($argument)
    $guard = Sensitive.new("/bin/test -e ${argument_shell}")
  } else {
    $guard = undef
  }
  exec { 'example': command => '/bin/true', unless => $guard }
}

test_shell_scope_and_multiple_assignment.code:
class example (String $argument) {
  if $argument == 'example' {
    $argument_shell = stdlib::shell_escape($argument)
  } else {
    $argument_shell = $argument
  }
  exec { 'demo': command => "/bin/echo ${argument_shell}" }
}

test_shell_scope_and_multiple_assignment.mapped:
class example (Array[String] $arguments) {
  $words_shell = $arguments.map |$argument| { stdlib::shell_escape($argument) }
  $command = join(['/bin/echo', join($words_shell, ' ')], ' ')
  exec { 'demo': command => $command }
}

